; cmp.asm -- chapter 11: A < E for every pair, unsigned and signed
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "cmp.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
TABLE   EQU $D000               ; 8 KB: D x 32 + E / 8 the byte, bit 7 first
; D < E for all 65,536 pairs, a bit each: first taken as unsigned, the carry
; after CP; the debugger reads the table at half. Then taken as signed, slt,
; into the same 8 KB: a 16 KB machine has room for one table at a time.
init:   di
        ld sp, SYS_AREA
        ld hl, TABLE
        ld d, 0                 ; D: the first number
u1:     ld e, 0                 ; E: the second
u2:     ld b, 8                 ; eight answers to a byte
u3:     ld a, d
        cp e                    ; the carry: D < E, unsigned
        rl c
        inc e
        djnz u3
        ld (hl), c
        inc hl
        ld a, e
        or a
        jr nz, u2               ; all 256 values of E
        inc d
        jr nz, u1               ; for all 256 values of D
half:   ld hl, TABLE
        ld d, 0                 ; D: the first number
s1:     ld e, 0                 ; E: the second
s2:     ld b, 8                 ; eight answers to a byte
s3:     ld a, d
        call slt                ; the carry: D < E, signed
        rl c
        inc e
        djnz s3
        ld (hl), c
        inc hl
        ld a, e
        or a
        jr nz, s2               ; all 256 values of E
        inc d
        jr nz, s1               ; for all 256 values of D
stop:   jr stop

; slt: the carry set if A < E, both taken as signed (-128 to 127). Uses A.
;      CP subtracts; without overflow S is the answer, and with overflow
;      it is upside down.
slt:    cp e                    ; A - E
        jp po, slt1             ; no overflow: S tells
        jp m, no                ; overflow, S = 1: A is not less
yes:    scf
        ret
slt1:   jp m, yes               ; no overflow, S = 1: A is less
no:     or a                    ; the carry clear
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
